          <View style={{ flexDirection: "row", gap: 6, marginBottom: 16 }}>
            {[
              { value: "", label: `Todos: ${count("")}` },
              { value: "ativo", label: `Ativos: ${count("ativo")}` },
              { value: "pausado", label: `Pausados: ${count("pausado")}` },
              { value: "inativo", label: `Inativos: ${count("inativo")}` },
            ].map((option) => (
