    [feedback, setFeedback] = useState(""),
    [error, setError] = useState(""),
    [busy, setBusy] = useState(false),
    [detail, setDetail] = useState<EnrollmentDetail | null>(null),
    [confirmation, setConfirmation] = useState<{
      title: string;
      description: string;
      run: () => Promise<void>;
    } | null>(null);
