function Shortcut({
  title,
  caption,
  icon,
  onPress,
  primary = false,
}: {
  title: string;
  caption?: string;
  icon: string;
  onPress: () => void;
  primary?: boolean;
}) {
  const t = useTheme();
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={title}
      onPress={onPress}
      style={({ pressed }) => [
        styles.shortcut,
        {
          backgroundColor: primary ? t.accent : t.background,
          borderColor: primary ? t.accent : t.border,
          opacity: pressed ? 0.75 : 1,
        },
      ]}
    >
      <Text
        accessibilityElementsHidden
        importantForAccessibility="no"
        style={{
          color: primary ? "#fff" : t.accent,
          fontSize: 26,
          fontWeight: "700",
        }}
      >
        {icon}
      </Text>
      <Text
        style={{
          fontFamily: Fonts.sans,
          color: primary ? "#fff" : t.text,
          fontWeight: "700",
          fontSize: 14,
        }}
      >
        {title}
      </Text>
      {!!caption && (
        <Text
          style={{
            fontFamily: Fonts.sans,
            color: primary ? "#fff" : t.textSecondary,
            fontSize: 12,
            lineHeight: 18,
          }}
        >
          {caption}
        </Text>
      )}
    </Pressable>
  );
}

