    <Page resetKey={tab}>
      <ProfileHeader student={student} studentView={studentView} tab={tab} onNavigate={navigate}
        onBack={() => router.push((studentView ? "/" : "/alunos") as Href)} />
      <Notice error>{failure || error}</Notice>
