          <View style={addingWorkout ? { display: "none" } : s.row}>
            <Button
              disabled={pending}
              variant="secondary"
              onPress={() => setOpen(open === index ? null : index)}
            >
              {open === index ? "Recolher treino" : "Editar treino"}
            </Button>
            <Button
              disabled={pending}
              variant="secondary"
              onPress={() => {
                const copy = {
                  ...identifyWorkout({ ...w, exercises: w.exercises.map(e => ({ ...e, id: undefined, clientId: undefined })) }),
