              variant="secondary"
              onPress={() => {
                setData({ ...data, workouts: move(data.workouts, index, 1) });
                setOpen(null);
              }}
            >
              ↓
            </Button>
            <Button
              disabled={pending}
              variant="danger"
              onPress={() => setRemove(index)}
