                subtitle: "",
                instructions: "",
                exercises: [],
              },
            ],
          });
          setOpen(data.workouts.length);
        }}
      >
        + Adicionar treino
      </Button></View>
      {remove !== null && (
        <Confirm
          title="Excluir este treino?"
          description="Esta ação removerá o treino desta rotina ao salvar o plano."
          onClose={() => setRemove(null)}
          onConfirm={async () => {
            setData({
              ...data,
              workouts: data.workouts.filter((_, i) => i !== remove),
            });
            setOpen(null);
          }}
        />
      )}
    </SaveForm>
  );
}

