        </View>


      </Card>;
    })}
    {menu && <Dialog title="Opções da rotina" onClose={() => setMenu(false)}>
      <View style={{ gap: 12 }}>
        <Button onPress={() => { setMenu(false); edit?.(); }}>Editar plano</Button>
