          <Button onPress={() => { setEditing(actions); setActions(null); }}>Editar plano</Button>
          {actions.status !== "arquivado" && <Button variant="secondary" onPress={() => { setArchive(actions); setActions(null); }}>Arquivar plano</Button>}
        </View>
      </Dialog>}
      {archive && (
        <Confirm
