          description="O plano sairá dos planos ativos. O histórico publicado permanece disponível ao aluno."
          onClose={() => setArchive(null)}
          onConfirm={async () => {
            await api(`/workout-plans/${archive.id}`, "PUT", {
              ...archive,
              status: "arquivado",
            });
            setSuccess("Plano arquivado.");
            await reload();
          }}
        />
      )}
    </View>
  );
}

