export function move<T>(items: T[], index: number, step: number) {
  const next = [...items];
  if (index + step < 0 || index + step >= next.length) return next;
  const [item] = next.splice(index, 1); next.splice(index + step, 0, item);
  return next;
}

export function move<T>(items: T[], index: number, step: number) {
  const next = [...items];
  if (index + step < 0 || index + step >= next.length) return next;
  const [item] = next.splice(index, 1); next.splice(index + step, 0, item);
  return next;
}

