          <Label muted>Seu dia de trabalho começa aqui.</Label>
        </View>
      </View>
      <Notice error>{students.error}</Notice>
      {students.error && (
        <Button
          variant="secondary"
          onPress={() => {
            void students.reload();
          }}
        >
