                >
                  <View style={{ flex: 1 }}>
                    <Label bold>{student.name}</Label>
                    <Label muted size={12}>
                      {student.mainGoal}
                    </Label>
                  </View>
                  <Label size={22}>›</Label>
                </Pressable>
              ))}
            </Card>
          )}
        </View>
