{"behavior":[{"confidence":"observed","description":"Contém JSX que referencia Button, Choices, Confirm, Field, Label, Notice, Section, View; a execução visual não foi testada.","evidence":[{"end_line":313,"snippet":"export function EvaluationForm({
  student,
  templates,
  programs,
  evaluation,
  onSaved,
  studentView = false,
}: {
  student: Student;
  templates: Template[];
  programs: Program[];
  evaluation?: Evaluation;
  onSaved: () => void;
  studentView?: boolean;
}) {
  const { user } = useSession();
  const t = useTheme();
  const [templateId, setTemplateId] = useState(
    evaluation?.templateId ?? templates[0]?.id ?? "",
  );
  const template =
    evaluation?.template ?? templates.find((x) => x.id === templateId);
  const [answers, setAnswers] = useState<Record<string, string>>(
    Object.fromEntries(
      evaluation?.answers.map((a) => [a.questionId, a.value]) ?? [],
    ),
  );
  const [date, setDate] = useState(evaluation?.date ?? today());
  const [cycle, setCycle] = useState(
    String(
      evaluation?.cycle ??
        Math.max(0, ...student.evaluations.map((e) => e.cycle)) + 1,
