    try {
      const answerList = Object.entries(answers).map(([questionId, value]) => ({
        questionId,
        value,
      }));
      const result = studentView
        ? await api<Evaluation>(
            `/me/students/${student.id}/evaluations/${id}`,
            "PUT",
            { answers: answerList },
          )
        : await api<Evaluation>(
            `/students/${student.id}/evaluations${id ? `/${id}` : ""}`,
