            <View style={{ backgroundColor: t.accentSoft, borderRadius: 20, width: 36, height: 36, alignItems: "center", justifyContent: "center" }}><Label size={22}>{icon}</Label></View>
            <Label size={12}>{label}</Label>
          </Pressable>)}
      </View>
    </Card>
