            <Label size={11} bold>{label}</Label>
          </View>;
        })}
      </View>
      <Label size={11} muted>{student.weeklyFrequency}× por semana planejados · ✓ realizado · × ausência · · previsto</Label>
    </Card>
    <Card style={card}>
      <Label size={13} bold>Engajamento do aluno</Label>
