          onClose={() => setRemove(null)}
          onConfirm={async () => {
            setData({
              ...data,
              workouts: data.workouts.filter((_, i) => i !== remove),
            });
            setOpen(null);
          }}
        />
      )}
    </SaveForm>
  );
