{"behavior":[{"confidence":"observed","description":"Contém JSX que referencia Button, Card, Confirm, Dialog, Label, Notice, PlanCard, PlanDetails, PlanForm, Pressable, View, WorkoutScreen; a execução visual não foi testada.","evidence":[{"end_line":303,"snippet":"export function WorkoutPlans({
  studentId,
  studentView = false,
  route,
}: {
  route?: WorkoutRoute;
  studentId?: string;
  studentView?: boolean;
}) {
  const { data, loading, error, reload } = useResource<Plan[]>(
    studentView ? "/me/workout-plans" : `/students/${studentId}/workout-plans`,
  );
  const t = useTheme();
  const [section, setSection] = useState("Rotinas de treino");
  const [filter, setFilter] = useState("Todas");
  const [localSelected, setLocalSelected] = useState<string | null>(null);
  const selected = route ? route.planId ?? null : localSelected;
  const setSelected = (id: string | null) => route ? route.selectPlan(id ?? undefined) : setLocalSelected(id);
  const [actions, setActions] = useState<Plan | null>(null);
  const [initialGroup, setInitialGroup] = useState<string | undefined>();
  const [initialPicker, setInitialPicker] = useState(false);
  const [initialTemplatePicker, setInitialTemplatePicker] = useState(false);
  const [initialWorkout, setInitialWorkout] = useState<number | null>(null);
  const [addingWorkout, setAddingWorkout] = useState(false);
  const [editing, setEditing] = useState<Plan | "new" | null>(null);
  const [programPicker, setProgramPicker] = useState(false);
  const [programData, setProgramData] = useState<PlanData | undefined>();
  const programs = useResource<Program[]>(programPicker ? "/programs" : null);
  const [archive, setArchive] = useState<Plan | null>(null);
  const [discard, setDiscard] = useState(false);
  const [childScreen, setChildScreen] = useState(false);
  const [success, setSuccess] = useState("");
  const plans =
    data?.filter((p) => !studentId || p.studentId === studentId) ?? [];
  const selectedPlan = plans.find(p => p.id === selected);
  const visible = plans.filter(p => {
    if (section === "Arquivadas") return p.status === "arquivado";
    if (p.status === "arquivado") return false;
    if (filter === "Rascunhos") return p.status === "rascunho";
    if (filter === "Atuais") return p.status === "ativo" && p.startsAt <= today() && (!p.endsAt || p.endsAt >= today());
    if (filter === "Futuras") return p.status === "ativo" && p.startsAt > today();
    if (filter === "Encerradas") return p.status === "ativo" && !!p.endsAt && p.endsAt < today();
    return true;
  });
  if (editing && studentId) return <>
        <WorkoutScreen
          hideHeader={childScreen}
          title={addingWorkout ? "Adicionar treino" : editing === "new" ? "Criar plano" : "Editar plano"}
          backLabel="Voltar à rotina"
          back={() => setDiscard(true)}
        >
          <PlanForm
            initialData={programData}
            addingWorkout={addingWorkout}
            screenChanged={setChildScreen}
            studentId={studentId}
            initialWorkout={initialWorkout}
            initialPicker={initialPicker}
            initialGroup={initialGroup}
            initialTemplatePicker={initialTemplatePicker}
            plan={editing === "new" ? undefined : editing}
            cancel={() => setDiscard(true)}
            done={() => {
              if (editing === "new") {
                setSection("Rotinas de treino");
                setFilter("Todas");
                setSelected(null);
              }
              setInitialWorkout(null); setInitialPicker(false); setInitialGroup(undefined);
              setInitialTemplatePicker(false);
              setEditing(null);
              setProgramData(undefined);
              setAddingWorkout(false);
              setSuccess(addingWorkout ? "Treino adicionado com sucesso." : "Plano salvo com sucesso.");
              void reload();
            }}
          />
        </WorkoutScreen>
      {discard && (
        <Confirm
          title="Descartar alterações não salvas?"
          description={addingWorkout ? "O novo treino ainda não foi salvo." : "As alterações do plano ainda não foram enviadas."}
          onClose={() => setDiscard(false)}
          onConfirm={async () => { setEditing(null); setProgramData(undefined); setAddingWorkout(false); setInitialWorkout(null); setInitialPicker(false); setInitialTemplatePicker(false); }}
        />
      )}
  </>;
  return (
    <View style={{ gap: 12 }}>
      <Notice>{success}</Notice>
      <Notice error>{error}</Notice>
      {loading && <Notice>Carregando rotinas…</Notice>}
      {error && <Button onPress={() => void reload()}>Tentar novamente</Button>}
      {selectedPlan ? <>
        {!route?.workoutId && <View style={{ alignSelf: "flex-start" }}><Button variant="secondary" onPress={() => setSelected(null)}>‹ Todas as rotinas</Button></View>}
        <PlanDetails key={selectedPlan.id} route={route} plan={selectedPlan} studentView={studentView} reload={reload}
