        <Button disabled={busy} variant="secondary" onPress={() => setPreset("load")}>Adicionar preset</Button>
        <Button disabled={busy} variant="secondary" onPress={() => setPreset(preset === "save" ? null : "save")}>Salvar como preset</Button>
      </View>
