        <Button disabled={busy || !name.trim()} onPress={() => void run(async () => { await api("/prescription-presets", "POST", { name: name.trim(), series: parse(rows) }); setPreset(null); setName(""); setSuccess("Preset salvo."); })}>Salvar preset</Button>
